<?php
session_start();if(!isset($_SESSION['admin'])){header('Location: ../index.php');exit;}require_once __DIR__.'/../config/db.php';require_once __DIR__.'/admincheck_role.php';
$campaigns=$conn->query("SELECT c.*,COUNT(k.id) kpi_count,COALESCE(SUM(k.weight),0) total_weight FROM performance_campaigns c LEFT JOIN campaign_kpis k ON k.campaign_id=c.id WHERE c.is_active=1 GROUP BY c.id ORDER BY c.name")->fetch_all(MYSQLI_ASSOC);$msg='';$errors=[];
function campaignWeightIsComplete(mysqli $conn, int $campaignId): bool { $s=$conn->prepare('SELECT COALESCE(SUM(weight),0) total FROM campaign_kpis WHERE campaign_id=?');$s->bind_param('i',$campaignId);$s->execute();return abs((float)$s->get_result()->fetch_assoc()['total']-100)<0.001; }
if(isset($_GET['template'])&&!campaignWeightIsComplete($conn,(int)$_GET['template'])){http_response_code(422);exit('Campaign KPI weights must total exactly 100 before downloading a template.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$upload=$_FILES['file']??null;$extension=$upload?strtolower(pathinfo((string)$upload['name'],PATHINFO_EXTENSION)):'';if(!$upload||($upload['size']??0)>5*1024*1024||$extension!=='csv'){$_FILES['file']['error']=UPLOAD_ERR_EXTENSION;}if(!campaignWeightIsComplete($conn,(int)($_POST['campaign_id']??0))){$_POST['campaign_id']=0;}}
if(isset($_GET['template'])){$cid=(int)$_GET['template'];$s=$conn->prepare('SELECT kpi_name,kpi_code,weight FROM campaign_kpis WHERE campaign_id=? ORDER BY display_order,id');$s->bind_param('i',$cid);$s->execute();$kpis=$s->get_result()->fetch_all(MYSQLI_ASSOC);if(!$kpis)exit('Add campaign KPIs first.');header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="campaign-performance-template.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');$head=['employee_code'];foreach($kpis as $k)$head[]=$k['kpi_code'].'_'.$k['weight'];$head[]='remarks';fputcsv($o,$head);$sample=['00001'];foreach($kpis as $k)$sample[]=$k['weight'];$sample[]='Performance remarks';fputcsv($o,$sample);fclose($o);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ems_verify_csrf();$cid=(int)($_POST['campaign_id']??0);$month=(int)($_POST['month']??0);$year=(int)($_POST['year']??0);if(!$cid||$month<1||$month>12||$year<2020||!isset($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK){$errors[]='Campaign, period and CSV file are required.';}else{$ks=$conn->prepare('SELECT id,kpi_name,kpi_code,weight FROM campaign_kpis WHERE campaign_id=? ORDER BY display_order,id');$ks->bind_param('i',$cid);$ks->execute();$kpis=$ks->get_result()->fetch_all(MYSQLI_ASSOC);$h=fopen($_FILES['file']['tmp_name'],'r');$header=fgetcsv($h);if($header)$header[0]=preg_replace('/^\xEF\xBB\xBF/','',$header[0]);$map=array_flip($header?:[]);$expected=['employee_code','remarks'];foreach($kpis as $k)$expected[]=$k['kpi_code'].'_'.$k['weight'];if(!$kpis||array_diff($expected,$header?:[])){$errors[]='CSV does not match this campaign template.';}else{$row=1;$done=0;while(($d=fgetcsv($h))!==false){$row++;$code=trim($d[$map['employee_code']]??'');if($code==='')continue;$e=$conn->prepare('SELECT id FROM employees WHERE employee_id=? OR CAST(employee_id AS UNSIGNED)=CAST(? AS UNSIGNED) LIMIT 1');$e->bind_param('ss',$code,$code);$e->execute();$er=$e->get_result()->fetch_assoc();if(!$er){$errors[]="Row $row: Employee code $code not found.";continue;}$scores=[];$valid=true;$total=0;foreach($kpis as $k){$col=$k['kpi_code'].'_'.$k['weight'];$score=(float)($d[$map[$col]]??-1);if($score<0||$score>(float)$k['weight'])$valid=false;$scores[(int)$k['id']]=$score;$total+=$score;}if(!$valid){$errors[]="Row $row: KPI score exceeds allowed weight.";continue;}$grade=$total>=95?'A+':($total>=90?'A':($total>=85?'B+':($total>=80?'B':($total>=70?'C':($total>=60?'D':'F')))));$remarks=trim($d[$map['remarks']]??'');$eid=(int)$er['id'];$admin=(int)($_SESSION['admin_id']??0);$p=$conn->prepare('INSERT INTO campaign_performance(employee_id,campaign_id,period_month,period_year,total_score,grade,remarks,uploaded_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE total_score=VALUES(total_score),grade=VALUES(grade),remarks=VALUES(remarks),uploaded_by=VALUES(uploaded_by),created_at=CURRENT_TIMESTAMP,id=LAST_INSERT_ID(id)');$p->bind_param('iiiidssi',$eid,$cid,$month,$year,$total,$grade,$remarks,$admin);$p->execute();$pid=(int)$conn->insert_id;foreach($scores as $kid=>$score){$x=$conn->prepare('INSERT INTO campaign_performance_scores(performance_id,kpi_id,score) VALUES(?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score)');$x->bind_param('iid',$pid,$kid,$score);$x->execute();}$done++;}$msg="$done employee campaign performance record(s) uploaded.";}fclose($h);}}
$recent=$conn->query('SELECT p.*,e.employee_id employee_code,e.full_name,c.name campaign_name FROM campaign_performance p JOIN employees e ON e.id=p.employee_id JOIN performance_campaigns c ON c.id=p.campaign_id ORDER BY p.id DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign Performance Upload</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.card{border:0;border-radius:16px;box-shadow:0 7px 22px #16345c12}.top{background:#173a70;color:#fff}</style></head><body><header class="top p-4"><div class="d-flex justify-content-between"><div><h2>Campaign Performance Bulk Upload</h2><div class="opacity-75">Dynamic template based on each campaign's KPIs</div></div><a href="campaign_kpi_setup.php" class="btn btn-light">Campaign Setup</a></div></header><main class="container-fluid p-4"><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><?php if($errors):?><div class="alert alert-warning"><ul class="mb-0"><?php foreach($errors as $e):?><li><?=htmlspecialchars($e)?></li><?php endforeach;?></ul></div><?php endif;?>
<div class="card p-4 mb-4"><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><div class="col-md-4"><label class="form-label">Campaign</label><select id="campaign" name="campaign_id" class="form-select" required><option value="">Select Campaign</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?> · <?=$c['kpi_count']?> KPIs · <?=$c['total_weight']?>%</option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Month</label><select name="month" class="form-select"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$m==date('n')?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor;?></select></div><div class="col-md-2"><label class="form-label">Year</label><input type="number" name="year" value="<?=date('Y')?>" class="form-control"></div><div class="col-md-4"><label class="form-label">Campaign CSV</label><input type="file" name="file" accept=".csv" class="form-control" required></div><div class="col-12 d-flex gap-2"><button type="button" class="btn btn-outline-success" onclick="if(campaign.value)location.href='?template='+campaign.value"><i class="fa fa-download"></i> Download Campaign Template</button><button class="btn btn-success"><i class="fa fa-upload"></i> Upload Performance</button></div></form></div>
<div class="card overflow-hidden"><div class="p-3"><h4>Recent Campaign Performance</h4></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Employee</th><th>Campaign</th><th>Period</th><th>Total</th><th>Grade</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=htmlspecialchars($r['employee_code'].' - '.$r['full_name'])?></td><td><?=htmlspecialchars($r['campaign_name'])?></td><td><?=date('F',mktime(0,0,0,$r['period_month'],1)).' '.$r['period_year']?></td><td><?=$r['total_score']?> / 100</td><td><strong><?=$r['grade']?></strong></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
